from django.db import migrations, models


def pasar_barrios_y_campana(apps, schema_editor):
    """Las zonas existentes pasan a la primera campaña y conservan sus barrios."""
    Zona = apps.get_model("core", "Zona")
    Barrio = apps.get_model("core", "Barrio")
    Campana = apps.get_model("core", "Campana")
    if not Zona.objects.exists():
        return
    campana = Campana.objects.order_by("id_campana").first() or Campana.objects.create(nombre="Campaña principal")
    Zona.objects.filter(campana__isnull=True).update(campana=campana)
    # Se usa la tabla intermedia directamente: el FK viejo (Barrio.zona) todavía
    # existe y su acceso inverso se llama igual que el nuevo campo
    Intermedia = Zona._meta.get_field("barrios").remote_field.through
    Intermedia.objects.bulk_create(
        Intermedia(zona_id=zona_id, barrio_id=barrio_id)
        for barrio_id, zona_id in Barrio.objects.exclude(zona__isnull=True).values_list("pk", "zona_id")
    )


